go_home()
obs = observe()
obj = obs["objects"]["purple_book"]
zone = obs["zones"]["purple_box"]
PI = 3.141592653589793
target_yaw = obj["short_axis_yaw"]
grip_h = max(0.018, min(0.024, obj["height"] - 0.003))

def adiff(a, b):
    d = (a - b) % PI
    if d > PI / 2:
        d -= PI
    return abs(d)

cands = grasp_candidates("purple_book")
viable = []
for c in cands:
    if not c.get("fits_open_fingers", True):
        continue
    if c.get("hand_clear") is False or c.get("fingers_clear") is False:
        continue
    if c.get("tilt_deg", 0) > 25:
        continue
    d = adiff(c.get("yaw", target_yaw), target_yaw)
    viable.append((d, -c.get("score", 0.5), c))
viable.sort(key=lambda t: (t[0], t[1]))

held = False
for _, _, c in viable:
    if adiff(c.get("yaw", target_yaw), target_yaw) > 0.6:
        continue
    c["yaw"] = target_yaw
    c["height"] = grip_h
    res = grasp(c)
    if res.get("holding_something", False):
        held = True
        break

if not held:
    for _, _, c in viable:
        c["yaw"] = target_yaw
        c["height"] = grip_h
        res = grasp(c)
        if res.get("holding_something", False):
            held = True
            break

if held:
    place_in_zone(zone, 0.18, 0.12)
    check("purple_book", "purple_box")
